module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic in,
    output logic disc,
    output logic flag,
    output logic err
);

    typedef enum logic [3:0] {
        S0   = 4'd0,
        S1   = 4'd1,
        S2   = 4'd2,
        S3   = 4'd3,
        S4   = 4'd4,
        S5   = 4'd5,
        DISC = 4'd6,
        S6   = 4'd7,
        FLAG = 4'd8,
        S7   = 4'd9
    } state_t;

    state_t current_state, next_state;

    always_ff @(posedge clk) begin
        if (reset) begin
            current_state <= S0;
        end else begin
            current_state <= next_state;
        end
    end

    always_comb begin
        disc = 1'b0;
        flag = 1'b0;
        err  = 1'b0;

        next_state = current_state;

        case (current_state)
            S0: begin
                if (in) next_state = S1;
                else    next_state = S0;
            end
            S1: begin
                if (in) next_state = S2;
                else    next_state = S0;
            end
            S2: begin
                if (in) next_state = S3;
                else    next_state = S0;
            end
            S3: begin
                if (in) next_state = S4;
                else    next_state = S0;
            end
            S4: begin
                if (in) next_state = S5;
                else    next_state = S0;
            end
            S5: begin
                if (in) next_state = S6;
                else    next_state = DISC;
            end
            DISC: begin
                disc = 1'b1;
                if (in) next_state = S1;
                else    next_state = S0;
            end
            S6: begin
                if (in) next_state = S7;
                else    next_state = FLAG;
            end
            FLAG: begin
                flag = 1'b1;
                if (in) next_state = S1;
                else    next_state = S0;
            end
            S7: begin
                err = 1'b1;
                if (in) next_state = S7;
                else    next_state = S0;
            end
            default: begin
                next_state = S0;
            end
        endcase
    end

endmodule

