module tb_TopModule;
    logic clk;
    logic reset;
    logic in;
    logic disc;
    logic flag;
    logic err;

    TopModule dut (
        .clk(clk),
        .reset(reset),
        .in(in),
        .disc(disc),
        .flag(flag),
        .err(err)
    );

    // Clock generator
    always #5 clk = ~clk;

    task send_bits(input string s);
        integer i;
        begin
            for (i = 0; i < s.len(); i = i + 1) begin
                @(posedge clk);
                #1;
                in = (s[i] == "1") ? 1'b1 : 1'b0;
            end
            @(posedge clk);
            #1;
        end
    endtask

    initial begin
        clk = 0;
        reset = 1;
        in = 0;
        @(posedge clk);
        @(posedge clk);
        #1;
        reset = 0;
        @(posedge clk);

        // Test 1: Disc sequence: 0111110
        // We start with previous=0 (from reset), so input sequence "0111110"
        $display("Testing disc: 0111110");
        // in is already 0, then 1, 1, 1, 1, 1, 0
        send_bits("0111110");
        // Expect disc to be high on the cycle after the last bit (0)
        // Wait, let's check when disc is asserted:
        // When '0' of 0111110 arrives at S5, next_state is DISC. On next posedge, current_state becomes DISC, disc=1.
        // So after send_bits("0111110"), on the next posedge we check outputs.
        @(posedge clk);
        #1;
        if (disc !== 1'b1 || flag !== 1'b0 || err !== 1'b0) begin
            $display("SELFTEST FAIL: disc sequence failed. disc=%b flag=%b err=%b", disc, flag, err);
            $finish;
        end

        // Test 2: Flag sequence: 01111110
        $display("Testing flag: 01111110");
        send_bits("01111110");
        @(posedge clk);
        #1;
        if (disc !== 1'b0 || flag !== 1'b1 || err !== 1'b0) begin
            $display("SELFTEST FAIL: flag sequence failed. disc=%b flag=%b err=%b", disc, flag, err);
            $finish;
        end

        // Test 3: Error sequence: 01111111
        $display("Testing err: 01111111");
        send_bits("01111111");
        @(posedge clk);
        #1;
        if (disc !== 1'b0 || flag !== 1'b0 || err !== 1'b1) begin
            $display("SELFTEST FAIL: err sequence failed. disc=%b flag=%b err=%b", disc, flag, err);
            $finish;
        end

        // Test 4: Continuing error with more 1s, then clearing with 0
        $display("Testing err continuation and clear");
        @(posedge clk);
        #1;
        in = 1'b1; // another 1
        @(posedge clk);
        #1;
        if (err !== 1'b1) begin
            $display("SELFTEST FAIL: err should stay high on 1");
            $finish;
        end
        in = 1'b0; // 0 clears err
        @(posedge clk);
        #1;
        if (err !== 1'b0) begin
            $display("SELFTEST FAIL: err should go low on 0");
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule

module tb_TopModule;
    logic clk;
    logic reset;
    logic in;
    logic disc;
    logic flag;
    logic err;

    TopModule dut (
        .clk(clk),
        .reset(reset),
        .in(in),
        .disc(disc),
        .flag(flag),
        .err(err)
    );

    always #5 clk = ~clk;

    initial begin
        clk = 0;
        reset = 1;
        in = 0;
        @(posedge clk);
        @(posedge clk);
        #1;
        reset = 0;
        @(posedge clk);

        // Send 0, 1, 1, 1, 1, 1, 0
        $display("Time %0t: sending 0", $time);
        in = 0; @(posedge clk); #1;
        $display("Time %0t: sending 1", $time);
        in = 1; @(posedge clk); #1;
        $display("Time %0t: sending 1", $time);
        in = 1; @(posedge clk); #1;
        $display("Time %0t: sending 1", $time);
        in = 1; @(posedge clk); #1;
        $display("Time %0t: sending 1", $time);
        in = 1; @(posedge clk); #1;
        $display("Time %0t: sending 1", $time);
        in = 1; @(posedge clk); #1;
        $display("Time %0t: sending 0", $time);
        in = 0; @(posedge clk); #1;

        $display("Time %0t: after 0111110 -> disc=%b flag=%b err=%b", $time, disc, flag, err);

        @(posedge clk);
        #1;
        $display("Time %0t: next cycle -> disc=%b flag=%b err=%b", $time, disc, flag, err);

        $finish;
    end
endmodule

module tb_TopModule;
    logic clk;
    logic reset;
    logic in;
    logic disc;
    logic flag;
    logic err;

    TopModule dut (
        .clk(clk),
        .reset(reset),
        .in(in),
        .disc(disc),
        .flag(flag),
        .err(err)
    );

    always #5 clk = ~clk;

    task drive_bit(input bit b);
        begin
            @(posedge clk);
            #1;
            in = b;
        end
    endtask

    initial begin
        clk = 0;
        reset = 1;
        in = 0;
        @(posedge clk);
        @(posedge clk);
        #1;
        reset = 0;
        @(posedge clk);

        // Test 1: 0 1 1 1 1 1 0 -> DISC
        drive_bit(0);
        drive_bit(1);
        drive_bit(1);
        drive_bit(1);
        drive_bit(1);
        drive_bit(1);
        drive_bit(0); // 7th bit (0), completing 0111110

        // Now evaluate outputs on this clock cycle (or right after posedge)
        #1;
        $display("DISC test: disc=%b (expected 1)", disc);
        if (disc !== 1'b1 || flag !== 1'b0 || err !== 1'b0) begin
            $display("SELFTEST FAIL: disc test failed");
            $finish;
        end

        // Test 2: 0 1 1 1 1 1 1 0 -> FLAG
        drive_bit(0); // part of previous zero or new? Wait, the previous ending was 0, so we can continue with 1s.
        // We already sent 0 at the end of disc test. That 0 is the starting 0 of the next sequence!
        drive_bit(1);
        drive_bit(1);
        drive_bit(1);
        drive_bit(1);
        drive_bit(1);
        drive_bit(1); // 6th one
        drive_bit(0); // 0 completing 01111110 (FLAG)

        #1;
        $display("FLAG test: flag=%b (expected 1)", flag);
        if (disc !== 1'b0 || flag !== 1'b1 || err !== 1'b0) begin
            $display("SELFTEST FAIL: flag test failed");
            $finish;
        end

        // Test 3: 0 1 1 1 1 1 1 1 -> ERR
        drive_bit(0); // starting 0
        drive_bit(1);
        drive_bit(1);
        drive_bit(1);
        drive_bit(1);
        drive_bit(1);
        drive_bit(1); // 6th one
        drive_bit(1); // 7th one (ERR)

        #1;
        $display("ERR test: err=%b (expected 1)", err);
        if (disc !== 1'b0 || flag !== 1'b0 || err !== 1'b1) begin
            $display("SELFTEST FAIL: err test failed");
            $finish;
        end

        // Test 4: ERR continuation on another 1
        drive_bit(1); // 8th one
        #1;
        if (err !== 1'b1) begin
            $display("SELFTEST FAIL: err continuation failed");
            $finish;
        end

        // Test 5: ERR clear on 0
        drive_bit(0);
        #1;
        if (err !== 1'b0) begin
            $display("SELFTEST FAIL: err clear failed");
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule

module tb_TopModule;
    logic clk;
    logic reset;
    logic in;
    logic disc;
    logic flag;
    logic err;

    TopModule dut (
        .clk(clk),
        .reset(reset),
        .in(in),
        .disc(disc),
        .flag(flag),
        .err(err)
    );

    always #5 clk = ~clk;

    initial begin
        clk = 0;
        reset = 1;
        in = 0;
        repeat(2) @(posedge clk);
        reset = 0;
        @(posedge clk);

        // Test 1: 0 1 1 1 1 1 0 -> DISC
        in = 0; @(posedge clk);
        in = 1; @(posedge clk);
        in = 1; @(posedge clk);
        in = 1; @(posedge clk);
        in = 1; @(posedge clk);
        in = 1; @(posedge clk);
        in = 0; @(posedge clk); // 7th bit (0)

