        if (disc !== 1'b1 || flag !== 1'b0 || err !== 1'b0) begin
            $display("SELFTEST FAIL: disc test failed");
            $finish;
        end

        // Test 2: 0 1 1 1 1 1 1 0 -> FLAG
        // Note: previous input was 0 (from above), so we send 6 ones then 0
        in = 1; @(posedge clk);
        in = 1; @(posedge clk);
        in = 1; @(posedge clk);
        in = 1; @(posedge clk);
        in = 1; @(posedge clk);
        in = 1; @(posedge clk);
        in = 0; @(posedge clk);

        #1;
        $display("FLAG test: disc=%b flag=%b err=%b", disc, flag, err);
        if (disc !== 1'b0 || flag !== 1'b1 || err !== 1'b0) begin
            $display("SELFTEST FAIL: flag test failed");
            $finish;
        end

        // Test 3: 0 1 1 1 1 1 1 1 -> ERR
        in = 1; @(posedge clk);
        in = 1; @(posedge clk);
        in = 1; @(posedge clk);
        in = 1; @(posedge clk);
        in = 1; @(posedge clk);
        in = 1; @(posedge clk);
        in = 1; @(posedge clk); // 7th one

        #1;
        $display("ERR test: disc=%b flag=%b err=%b", disc, flag, err);
        if (disc !== 1'b0 || flag !== 1'b0 || err !== 1'b1) begin
            $display("SELFTEST FAIL: err test failed");
            $finish;
        end

        // Test 4: ERR continuation on another 1
        in = 1; @(posedge clk);
        #1;
        if (err !== 1'b1) begin
            $display("SELFTEST FAIL: err continuation failed");
            $finish;
        end

        // Test 5: ERR clear on 0
        in = 0; @(posedge clk);
        #1;
        if (err !== 1'b0) begin
            $display("SELFTEST FAIL: err clear failed");
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end
